<script setup lang="ts">
import { invoke } from "@tauri-apps/api/core";
import { computed, onMounted, ref } from "vue";
import { Boxes, Plus, RefreshCw } from "lucide-vue-next";
import PaginationControls from "../components/PaginationControls.vue";
interface Product { id: number; name: string }
interface Variant { id: number; product_id: number; product_name: string; sku: string; name: string; purchase_price: number; selling_price: number; current_stock: number; minimum_stock: number }
const variants = ref<Variant[]>([]); const products = ref<Product[]>([]); const page = ref(1); const pageSize = 8; const productId = ref<number | null>(null); const sku = ref(""); const variantName = ref(""); const purchasePrice = ref(0); const sellingPrice = ref(0); const minimumStock = ref(0); const selectedVariant = ref<number | null>(null); const quantity = ref(0); const reason = ref(""); const loading = ref(true); const error = ref(""); const message = ref("");
const pagedVariants = computed(() => variants.value.slice((page.value - 1) * pageSize, page.value * pageSize));
const formatMoney = (value: number) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(value);
async function load() { loading.value = true; error.value = ""; try { [variants.value, products.value] = await Promise.all([invoke<Variant[]>("list_variants", { productId: null }), invoke<Product[]>("list_products")]); page.value = 1; } catch (e) { error.value = String(e); } finally { loading.value = false; } }
async function addVariant() { error.value = ""; message.value = ""; if (!productId.value || !variantName.value.trim()) { error.value = "Produk dan nama varian wajib diisi."; return; } try { const generatedSku = sku.value.trim() || `SKU-${Date.now().toString(36).toUpperCase()}`; await invoke("create_variant", { input: { product_id: productId.value, sku: generatedSku, name: variantName.value, purchase_price: purchasePrice.value, selling_price: sellingPrice.value, minimum_stock: minimumStock.value } }); sku.value = ""; variantName.value = ""; await load(); message.value = `Varian berhasil dibuat dengan SKU ${generatedSku}.`; } catch (e) { error.value = String(e); } }
async function adjustStock() { error.value = ""; message.value = ""; if (!selectedVariant.value || quantity.value === 0 || !reason.value.trim()) { error.value = "Pilih varian, isi jumlah perubahan, dan alasan."; return; } try { await invoke("adjust_stock", { input: { variant_id: selectedVariant.value, quantity: quantity.value, reason: reason.value } }); quantity.value = 0; reason.value = ""; await load(); message.value = "Stok berhasil diperbarui."; } catch (e) { error.value = String(e); } }
onMounted(load);
</script>

<template><section class="module-page"><div class="section-intro"><div><p class="eyebrow">Operasional</p><h2>Inventori</h2><p class="intro-copy">Kelola varian dan lakukan penyesuaian stok dengan catatan pergerakan.</p></div><button class="secondary-button" type="button" @click="load"><RefreshCw :size="15" /> Segarkan</button></div><p v-if="error" class="form-error">{{ error }}</p><p v-if="message" class="form-success">{{ message }}</p><div class="content-columns"><form class="panel form-panel" @submit.prevent="addVariant"><div class="panel-heading"><div><p class="eyebrow">Katalog</p><h3>Tambah varian</h3></div><Plus :size="18" class="panel-icon" /></div><label>Produk<select v-model="productId"><option :value="null">Pilih produk</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }}</option></select></label><label>Nama varian<input v-model="variantName" placeholder="Contoh: 250g" /></label><label>SKU <span class="optional">opsional</span><input v-model="sku" placeholder="Kosongkan untuk membuat otomatis" /></label><div class="form-row"><label>Harga beli<input v-model.number="purchasePrice" type="number" min="0" /></label><label>Harga jual<input v-model.number="sellingPrice" type="number" min="0" /></label></div><label>Batas stok minimum<input v-model.number="minimumStock" type="number" min="0" /></label><button class="primary-button" type="submit">Simpan varian</button></form><form class="panel form-panel" @submit.prevent="adjustStock"><div class="panel-heading"><div><p class="eyebrow">Pergerakan manual</p><h3>Sesuaikan stok</h3></div><Boxes :size="18" class="panel-icon" /></div><label>Varian<select v-model="selectedVariant"><option :value="null">Pilih varian</option><option v-for="variant in variants" :key="variant.id" :value="variant.id">{{ variant.product_name }} â€” {{ variant.name }} ({{ variant.current_stock }})</option></select></label><label>Jumlah perubahan<input v-model.number="quantity" type="number" placeholder="Gunakan - untuk pengurangan" /></label><label>Alasan<textarea v-model="reason" rows="4"></textarea></label><button class="primary-button" type="submit">Catat perubahan stok</button></form></div><section class="panel table-panel paginated-panel"><div class="panel-heading"><div><p class="eyebrow">Saldo saat ini</p><h3>Varian inventori</h3></div><span class="neutral-chip">{{ variants.length }} varian</span></div><div v-if="loading" class="table-state">Memuat data...</div><div v-else-if="!variants.length" class="table-state"><Boxes :size="22" /><strong>Belum ada varian</strong><span>Buat produk dan varian untuk mulai melacak stok.</span></div><template v-else><table><thead><tr><th>Produk / varian</th><th>SKU</th><th>Stok</th><th>Minimum</th><th>Harga jual</th></tr></thead><tbody><tr v-for="variant in pagedVariants" :key="variant.id"><td class="cell-strong">{{ variant.product_name }} / {{ variant.name }}</td><td>{{ variant.sku }}</td><td :class="{ 'low-stock': variant.current_stock <= variant.minimum_stock }">{{ variant.current_stock }}</td><td>{{ variant.minimum_stock }}</td><td>{{ formatMoney(variant.selling_price) }}</td></tr></tbody></table><PaginationControls v-model:page="page" :total="variants.length" :page-size="pageSize" /></template></section></section></template>

